// 快慢指針判圈：最終不是到 1 就是進入循環
// 時間複雜度: O(log n)，空間複雜度: O(1)
function isHappy(n) {
    const next = (x) => {
        let sum = 0;
        while (x > 0) {
            const d = x % 10;
            sum += d * d;
            x = Math.floor(x / 10);
        }
        return sum;
    };
    let slow = n, fast = next(n);
    while (fast !== 1 && slow !== fast) {
        slow = next(slow);
        fast = next(next(fast));
    }
    return fast === 1;
}

